.theme-toggle { display: inline-flex; align-items: center; gap: 0.4rem; padding: 0.4rem 0.75rem; font: inherit; font-size: 0.9rem; color: inherit; background: rgb(255 255 255 / 0.12); border: 1px solid rgb(255 255 255 / 0.4); border-radius: 999px; }
.theme-toggle:hover { background: rgb(255 255 255 / 0.22); }
.theme-toggle:focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }
.theme-toggle-icon { font-size: 1.1em; line-height: 1; }
